const part=type=>type==='actuator'?`<svg viewBox="0 0 260 260"><defs><linearGradient id="c"><stop stop-color="#687368"/><stop offset=".45" stop-color="#e7e9df"/><stop offset="1" stop-color="#778477"/></linearGradient></defs><g transform="rotate(-25 130 130)"><rect x="60" y="72" width="142" height="116" rx="25" fill="url(#c)" stroke="#657360"/><ellipse cx="70" cy="130" rx="40" ry="58" fill="#2b352c"/><ellipse cx="70" cy="130" rx="29" ry="43" fill="#a7b09e"/><ellipse cx="70" cy="130" rx="16" ry="26" fill="#313b2e"/><path d="M193 99h30v62h-30" fill="#28362c"/><path d="M110 87v86m12-86v86m12-86v86m12-86v86m12-86v86m12-86v86" stroke="#768171" stroke-width="3"/><circle cx="65" cy="93" r="4" fill="#d2e849"/><circle cx="65" cy="167" r="4" fill="#d2e849"/></g></svg>`:type==='hand'?`<svg viewBox="0 0 260 260"><g transform="rotate(20 130 130)" fill="#c8cec1" stroke="#5e6a5b" stroke-width="2"><rect x="82" y="113" width="82" height="92" rx="18"/><rect x="82" y="57" width="17" height="64" rx="8"/><rect x="105" y="35" width="17" height="88" rx="8"/><rect x="129" y="43" width="17" height="80" rx="8"/><rect x="152" y="66" width="17" height="62" rx="8"/><rect x="47" y="119" width="23" height="62" rx="10" transform="rotate(-30 60 150)"/><rect x="95" y="200" width="54" height="35" rx="5" fill="#354130"/><path d="M91 78h8m6-12h17m7 8h17m6 14h17M91 94h8m6-8h17m7 8h17m6 10h17"/><path d="M102 137h40v46h-40z" fill="#33412d"/><path d="M112 147h20v5h-20" stroke="#d5ed45"/></g></svg>`:`<svg viewBox="0 0 260 260"><g transform="rotate(-18 130 130)"><rect x="51" y="70" width="161" height="125" rx="8" fill="#344b39" stroke="#1f3023" stroke-width="3"/><rect x="102" y="100" width="58" height="58" rx="4" fill="#252e28" stroke="#839780" stroke-width="4"/><path d="M65 88h25v12H65zm0 25h25v12H65zm0 25h25v12H65z" fill="#c6d0b7"/><path d="M175 88h20v70h-20z" fill="#c1c7b6"/><path d="M66 180h128M113 86V73m13 13V73m13 13V73m13 13V73m-39 86v18m13-18v18m13-18v18m13-18v18" stroke="#d1db85" stroke-width="4"/><circle cx="60" cy="79" r="4" fill="#bcd94a"/><circle cx="202" cy="186" r="4" fill="#bcd94a"/></g></svg>`;
const base=[{id:1,name:'Atlas R1 · Research Edition',cat:'Robots',price:14900,seller:'Nova Robotscs',type:'robot',badge:'FEATURED',desc:'An illustrative humanoid research platform for motion control development and laboratory experiments.'},{id:2,name:'Harmonic Drive A80',cat:'Parts',price:349,seller:'Motion Lab',type:'actuator',badge:'COMPONENT',desc:'An example of a compact actuator for robotic joints. A live listing would include torque, weight, dimensions, and compatibility.'},{id:3,name:'Dexterous Hand · H5',cat:'Parts',price:1290,seller:'Dexter Works',type:'hand',badge:'MANIPULATION',desc:'An example robotic hand for developing grasping and object manipulation.'},{id:4,name:'Humanoid Starter Kit',cat:'Kits',price:2490,seller:'Open Motion',type:'board',badge:'FOR BUILDERS',desc:'An illustrative development kit with a controller, sensors, and essential components for a first robotics project.'},{id:5,name:'Biped Mini · Developer',cat:'Robots',price:5900,seller:'Open Motion',type:'robot',badge:'DEVELOPER PLATFORM',desc:'An example compact bipedal platform for learning and prototyping.'},{id:6,name:'Joint Module · J40',cat:'Parts',price:219,seller:'Motion Lab',type:'actuator',badge:'MODULAR',desc:'An example modular joint for experimental robotic systems.'},{id:7,name:'Vision & Control Kit',cat:'Kits',price:690,seller:'Nova Robotscs',type:'board',badge:'PERCEPTION',desc:'An example kit for perception and control development.'},{id:8,name:'Adaptive Gripper · G2',cat:'Parts',price:490,seller:'Dexter Works',type:'hand',badge:'GRASPING',desc:'An example adaptive gripper for laboratory projects.'}];
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))||d}catch{return d}},write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Your browser does not allow data storage.')}};let products=[...base,...read('hm-listings',[]).map(p=>({...p,cat:({Roboti:'Robots',Delovi:'Parts',Kitovi:'Kits'})[p.cat]||p.cat,seller:p.seller==='Moj oglas'?'My listing':p.seller,badge:p.badge==='MOJ DEMO OGLAS'?'MY DEMO LISTING':p.badge}))],favorites=read('hm-favorites',[]),cat='All',onlySaved=false;const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),art=p=>p.type==='robot'?robot():part(p.type);
$('#heroRobot').innerHTML=robot();
function render(){let q=$('#search').value.toLowerCase();let list=products.filter(p=>(cat==='All'||p.cat===cat)&&(!onlySaved||favorites.includes(p.id))&&(p.name+' '+p.cat+' '+p.seller).toLowerCase().includes(q));let sort=$('#sort').value;if(sort!=='featured')list.sort((a,b)=>sort==='low'?a.price-b.price:b.price-a.price);$('#results').textContent=`${list.length} products${onlySaved?' · Saved':''}`;$('#savedCount').textContent=favorites.length;$('#saved').style.color=onlySaved?'#829a15':'';$('#empty').hidden=list.length>0;$('#products').innerHTML=list.map(p=>`<article class="product"><div class="product-art" data-open="${p.id}" tabindex="0" role="button" aria-label="View ${esc(p.name)}"><span class="tag">${esc(p.badge)}</span><button class="heart ${favorites.includes(p.id)?'on':''}" data-save="${p.id}" aria-label="Save ${esc(p.name)}" aria-pressed="${favorites.includes(p.id)}">${favorites.includes(p.id)?'♥':'♡'}</button>${art(p)}</div><div class="category">${esc(p.cat.toUpperCase())}</div><h3 data-open="${p.id}">${esc(p.name)}</h3><div class="seller">${esc(p.seller)} · Demo seller</div><div class="product-bottom"><div>${money(p.price)} <small>/ unit</small></div><button data-open="${p.id}" aria-label="Product details">↗</button></div></article>`).join('');document.querySelectorAll('[data-cat]').forEach(b=>b.classList.toggle('active',b.dataset.cat===cat))}
function show(id){let p=products.find(p=>p.id===id);if(!p)return;$('#detailBody').innerHTML=`<div class="eyebrow">${esc(p.cat)} / DEMO PRODUCT</div><div class="detail-art">${art(p)}</div><h2>${esc(p.name)}</h2><p class="muted">${esc(p.seller)} · Illustrative listing</p><h2>${money(p.price)}</h2><p>${esc(p.desc)}</p><p class="muted">This is a marketplace demo. Checkout and seller messaging are not connected yet.</p><button class="dark" id="detailSave">${favorites.includes(id)?'Remove from saved':'Save product'} ♡</button>`;$('#detailSave').onclick=()=>{save(id);$('#detailSave').textContent=favorites.includes(id)?'Remove from saved ♡':'Save product ♡'};$('#detail').showModal()}
function save(id){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];write('hm-favorites',favorites);render()}
document.addEventListener('click',e=>{const s=e.target.closest('[data-save]');if(s){save(Number(s.dataset.save));return}const o=e.target.closest('[data-open]');if(o)show(Number(o.dataset.open))});document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.product-art')){e.preventDefault();show(Number(e.target.dataset.open))}});document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{cat=b.dataset.cat;onlySaved=false;render()});document.querySelectorAll('[data-nav]').forEach(a=>a.onclick=()=>{cat=a.dataset.nav;onlySaved=false;render()});$('#search').oninput=render;$('#sort').onchange=render;$('#saved').onclick=()=>{onlySaved=!onlySaved;render();$('#market').scrollIntoView()};$('#reset').onclick=()=>{cat='All';onlySaved=false;$('#search').value='';render()};document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());['#sell','#sell2'].forEach(s=>$(s).onclick=()=>$('#listing').showModal());let timer;function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',4000)}$('#listingForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);const p={id:Date.now(),name:f.get('name').trim(),cat:f.get('cat'),price:Number(f.get('price')),desc:f.get('desc').trim(),seller:'My listing',type:f.get('cat')==='Robots'?'robot':f.get('cat')==='Kits'?'board':'actuator',badge:'MY DEMO LISTING'};if(!p.name||!p.desc)return;products.push(p);write('hm-listings',products.filter(p=>p.id>8));cat='All';onlySaved=false;$('#search').value='';$('#sort').value='featured';render();$('#listing').close();e.target.reset();toast('Demo listing saved in this browser.');show(p.id)};render();
